template='''<!doctype html><meta charset="utf-8"><title>MIA5150 · Skill discovery lab</title>
<style>body{font:16px system-ui;background:#101725;color:#e8edf5;margin:0;padding:32px;max-width:1300px}h1{font-size:32px;margin:0}p{color:#b6c4d5;line-height:1.55}select,button{background:#223247;color:white;border:1px solid #526780;padding:10px;margin:5px;border-radius:8px}main{display:grid;grid-template-columns:1fr 1fr;gap:22px}.card{background:#1a2638;border-radius:12px;padding:20px}.hit{padding:10px;margin:8px 0;border-left:3px solid #7d8ca1}.gold{border-color:#66dab2;background:#18372f}.miss{color:#ffb9b9}small{color:#afbdd0}.pill{font-size:13px;padding:5px;color:#66dab2}#query{font-size:20px}ol{padding-left:24px}@media(max-width:800px){main{grid-template-columns:1fr}}</style>
<h1>Skill discovery lab</h1><p><strong>Full-query finding:</strong> fusion was essentially flat across all 4,392 public queries (NDCG@10 +0.000136; paired interval includes zero). This viewer explains the smaller development sample, not a confirmed overall gain.</p><p>One query, the same 6,006 skill headers, different discovery methods. This is a 128-query public development pilot, not a blind final test. Green marks labelled relevant skills. Missing labels and regressions remain visible.</p>
<div><label>Before <select id="a"></select></label><label>After <select id="b"></select></label><label>Cases <select id="filter"><option value="all">All queries</option><option value="wins">Improvements</option><option value="losses">Regressions</option><option value="ties">Ties</option></select></label></div>
<select id="cases"></select><button id="prev">Previous</button><button id="next">Next</button><p id="query"></p><p id="gold"></p><main><section id="left" class="card"></section><section id="right" class="card"></section></main><p id="note"></p>
<script>const D=PAYLOAD;const $=id=>document.getElementById(id);for(const n of Object.keys(D.systems)){for(const id of ['a','b']){let o=document.createElement('option');o.textContent=n;$(id).append(o)}}$('a').value='SkillRet embeddings';$('b').value='SkillRet + lexical fusion';function score(n,q){return D.metrics[n].per_query[q]['NDCG@10']}function list(){let old=$('cases').value;$('cases').replaceChildren();for(const q of D.queries){let d=score($('b').value,q.id)-score($('a').value,q.id),f=$('filter').value;if(f==='wins'&&d<=1e-8||f==='losses'&&d>=-1e-8||f==='ties'&&Math.abs(d)>1e-8)continue;let o=document.createElement('option');o.value=q.id;o.textContent=q.id+' · '+(d>=0?'+':'')+(100*d).toFixed(1)+' NDCG points';$('cases').append(o)}if([...$('cases').options].some(o=>o.value===old))$('cases').value=old;draw()}function draw(){let q=D.queries.find(x=>x.id===$('cases').value);if(!q){$('query').textContent='No cases match this filter.';return}$('query').textContent=q.query;$('gold').textContent='Relevant skills: '+Object.keys(D.labels[q.id]).map(d=>D.skills[d].name).join(' + ');for(const [side,n] of [['left',$('a').value],['right',$('b').value]]){let box=$(side);box.replaceChildren();let h=document.createElement('h2');h.textContent=n;box.append(h);let p=document.createElement('p');p.textContent='NDCG@10 '+score(n,q.id).toFixed(3);box.append(p);let hits=D.systems[n][q.id].slice(0,10);hits.forEach((d,i)=>{let el=document.createElement('div');el.className='hit'+(D.labels[q.id][d]?' gold':'');let title=document.createElement('strong');title.textContent=(i+1)+'. '+D.skills[d].name;el.append(title);let desc=document.createElement('p');desc.textContent=D.skills[d].description;el.append(desc);box.append(el)});let missing=Object.keys(D.labels[q.id]).filter(d=>!hits.includes(d));let m=document.createElement('p');m.className='miss';m.textContent=missing.length?'Missing from top 10: '+missing.map(d=>D.skills[d].name).join(', '):'All labelled skills appear in top 10.';box.append(m)}$('note').textContent='No gold IDs, skill names, or required-skill counts were passed to scoring. Gold labels are shown here only for explanation. Browse all cases rather than presenting only wins.'}for(const id of ['a','b','filter'])$(id).onchange=list;$('cases').onchange=draw;for(const [id,delta] of [['prev',-1],['next',1]])$(id).onclick=()=>{let s=$('cases');s.selectedIndex=(s.selectedIndex+delta+s.options.length)%s.options.length;draw()};list();</script>'''
